import heapq

def solve_shortest_paths(graph, start_node):
    if not graph:
        if start_node is None:
            return None
        else:
            return {start_node: 0}

    distances = {}
    for node in set(graph.keys()).union(*[list(neighbors.keys()) for neighbors in graph.values()]):
        distances[node] = float('inf')


    if start_node not in distances:
        distances[start_node] = float('inf')

    distances[start_node] = 0
    pq = [(0, start_node)]

    while pq:
        dist, current_node = heapq.heappop(pq)

        if dist > distances[current_node]:
            continue

        if current_node in graph:
            for neighbor, weight in graph[current_node].items():
                new_dist = dist + weight
                if new_dist < distances[neighbor]:
                    distances[neighbor] = new_dist
                    heapq.heappush(pq, (new_dist, neighbor))

    return {node: (distances[node] if distances[node] != float('inf') else "float('inf')") for node in distances}

